1	import { mkdir, writeFile } from "node:fs/promises";
2	import path from "node:path";
3	import { listAssets, findAssets, type AssetMatch } from "./index";
4	
5	// Bridges the asset catalogue to the SDK engine.
6	//
7	// The two engines reach assets by different routes, and that is deliberate
8	// rather than an inconsistency:
9	//
10	//  - The API engine (lib/agent.ts) has custom tools, so it gets a real
11	//    `find_assets` tool that returns matches over the wire.
12	//  - The SDK engine has a fixed toolset (Read/Write/Edit/Bash/Glob/Grep) and a
13	//    real working directory. Giving it a custom tool would mean an in-process
14	//    MCP server, whose `tool()` helper requires zod — which is only present as
15	//    a transitive dependency of the SDK, not a declared one. Depending on a
16	//    package that isn't in package.json is a silent breakage waiting for the
17	//    next install, so instead the catalogue is written to disk and the agent
18	//    uses the file tools it already has.
19	//
20	// The directory is dot-prefixed on purpose: readFileTree() in agent-sdk.ts
21	// skips any entry starting with ".", so the catalogue is invisible to the diff
22	// that turns the working directory back into project files. Rename it without
23	// the dot and every generated site gains 460-odd junk files.
24	
25	const DIR = ".kodely-assets";
26	
27	/**
28	 * Writes the catalogue into `workDir/.kodely-assets/`:
29	 *   INDEX.md          one line per asset — id, name, keywords
30	 *   <kind>/<name>.txt the paste-ready source for that asset
31	 *
32	 * Returns the number of assets written.
33	 */
34	export async function materializeAssets(workDir: string): Promise<number> {
35	  const root = path.join(workDir, DIR);
36	  // No kind filter — the whole catalogue.
37	  const all = listAssets(undefined, { limit: 1000 });
38	
39	  const byKind = new Map<string, AssetMatch[]>();
40	  for (const a of all) {
41	    const list = byKind.get(a.kind) ?? [];
42	    list.push(a);
43	    byKind.set(a.kind, list);
44	  }
45	
46	  await mkdir(root, { recursive: true });
47	
48	  const lines: string[] = [
49	    "# Kodely asset catalogue",
50	    "",
51	    "Every asset here is safe to inline — no external requests, so nothing here",
52	    "can be blocked by the published site's CSP.",
53	    "",
54	    "To use one: find its id below (Grep this file), then Read the file named on",
55	    "that line and paste its contents into the component you are writing.",
56	    "",
57	  ];
58	
59	  for (const [kind, assets] of [...byKind.entries()].sort()) {
60	    await mkdir(path.join(root, kind), { recursive: true });
61	    lines.push(`## ${kind} (${assets.length})`, "");
62	
63	    for (const a of assets) {
64	      // The id is namespaced ("icon:phone"); the bit after the colon is the
65	      // filename. Sanitised because it ends up as a real path.
66	      const leaf = a.id.split(":").slice(1).join("-").replace(/[^A-Za-z0-9._-]/g, "-") || "asset";
67	      const rel = `${DIR}/${kind}/${leaf}.txt`;
68	      await writeFile(
69	        path.join(root, kind, `${leaf}.txt`),
70	        `${a.usage}\n\n${a.source}\n`,
71	        "utf8",
72	      );
73	      lines.push(`- \`${a.id}\` — ${a.name} — ${a.keywords.slice(0, 6).join(", ")} → \`${rel}\``);
74	    }
75	    lines.push("");
76	  }
77	
78	  await writeFile(path.join(root, "INDEX.md"), lines.join("\n"), "utf8");
79	  return all.length;
80	}
81	
82	/**
83	 * Result shape for the API engine's `find_assets` tool. Trimmed to what the
84	 * model needs to paste — the full AssetMatch carries alternative encodings
85	 * that would multiply the token cost of every search for no benefit.
86	 */
87	export function formatMatchesForTool(matches: AssetMatch[]): string {
88	  if (matches.length === 0) {
89	    return "No assets matched. Try a broader term, or use a CSS gradient / inline SVG of your own.";
90	  }
91	  return matches
92	    .map((m) => [`### ${m.id} — ${m.name}`, m.usage, "", m.source].join("\n"))
93	    .join("\n\n---\n\n");
94	}
95	
96	export { findAssets };
